    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,1.5],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,2.5],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+1)*50,0.11,2.1,0.8],
    [400+Math.cos(t*0.55+2)*60,200+Math.sin(t*0.45+4)*70,0.05,1.8,1.2]
  ];
  let aS=0,iS=0,hrm=0;
  for(const[sX,sY,f,sp,ph]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp+ph);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5+ph);
    hrm+=Math.sin(d*f*1.4-t*sp*0.8+ph*2)*0.5;
  }
  const n=src.length,act=aS/n,inh=iS/n,h=hrm/n;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2+Math.sin(sx*0.08+sy*0.06-t*1.5)*0.3;
