  const r1=Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const r2=Math.tanh((h-act*0.5+inh*0.4+bg*0.2)*1.8);
  const cross=Math.tanh((r1+r2*0.6-Math.abs(r1*r2)*0.8)*1.5);
  const c1=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const c2=Math.tanh((Math.sin(sx*0.22+1)*Math.sin(sy*0.22+2)+Math.sin((sx-sy)*0.15+t*0.7)*0.3)*1.2)*0.2;
  const fine=Math.sin(sx*0.3+sy*0.2+t*3)*Math.sin(sx*0.2-sy*0.3-t*2.5)*0.15;
  const blend=cross*0.6+c1*0.2+c2*0.1+fine*0.1,v=blend*0.5+0.5;
  const pal=[[5,12,55],[12,55,95],[18,110,125],[30,155,135],[140,195,120],[220,200,80],[230,150,65],[200,90,70],[150,50,80],[90,25,65],[40,15,55],[5,12,55]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.75+Math.sin(cross*Math.PI)*0.25,edge=Math.abs(cross)>0.65?1.2:Math.abs(cross)>0.4?1.05:0.95,glow=Math.max(0,1-dist/250)*0.15;
  const le=lum*edge+glow;
  return[Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*le)|0,Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*le)|0,Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*le)|0];
